<?php require_once '../config/auth.php';require_role('siswa');if($_SERVER['REQUEST_METHOD']==='POST')deny_access();if(isset($_GET['nis']) && input_text($_GET,'nis',15)!==(string)user_reference())deny_access();$q=db()->prepare('SELECT j.*,mp.nama_mapel,g.nama_guru FROM jadwal j JOIN siswa s ON s.id_kelas=j.id_kelas JOIN mata_pelajaran mp ON mp.id_mapel=j.id_mapel JOIN guru g ON g.id_guru=j.id_guru WHERE s.nis=? AND j.status="aktif" AND mp.status="aktif" AND g.status="aktif" ORDER BY j.hari,j.jam_mulai');$q->execute([user_reference()]);$rows=$q->fetchAll();$page_title='Jadwal Kelas';require '../includes/header.php';require '../includes/sidebar.php'; ?><h2>Jadwal Kelas</h2><div class="card p-3"><table class="table"><thead><tr><th>Hari</th><th>Jam</th><th>Mapel</th><th>Guru</th><th>Ruang</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['hari']) ?></td><td><?= e(substr($r['jam_mulai'],0,5)) ?></td><td><?= e($r['nama_mapel']) ?></td><td><?= e($r['nama_guru']) ?></td><td><?= e($r['ruang']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php require '../includes/footer.php';
